E=lambda x:html.escape(str(x));style=re.search(r'<style>(.*?)</style>',(OLD/'PLAN-180.html').read_text(encoding='utf8'),re.S)[1]
def head(title):return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+'</title><style>'+style+'</style></head><body><main>'
def src(i):return '<a href="'+E(Path(assets[i]['path']).as_uri())+'">'+E(i)+' · '+E(Path(assets[i]['path']).name)+'</a>'
def gallery(p):return '<div class="assets">'+''.join('<a href="'+E(Path(assets[i]['path']).as_uri())+'"><img loading="lazy" src="../../archive-audit/'+('video-sheets/' if assets[i]['kind']=='video' else 'thumbs/')+i+'.jpg" alt="'+E(i)+'"><span>'+E(i)+'</span></a>' for i in p['asset_ids'])+'</div>'
intro='''<p class="eyebrow">yigitozen.art · Ayak 4 · kaynakla gerekçelendirilmiş öneri</p><h1>Tanıdık imgelerden kendi resim diline</h1><p class="lead">İlk karşılaşma tanıdık bir figür veya sahneden gelebilir. Takip edilecek şey, onun kütle, kontur ve mekânla başka bir resme dönüşmesidir. Tarihli eski işler aynı dilin bir karaktere veya güncel referansa bağlı olmadığını gösterir.</p><p class="notice">Bu, sanatçı adına kabul edilmiş statement değil, araştırmadaki eser haritasından çıkarılmış editoryal öneridir. İlk 14 gün için 6 gerekçeli içerik kartı; 180 gün için 6 bölüm havuzu var. Sonraki 166 günün tek tek eseri/caption’ı atanmış değil. Önceki 78 yayınlık sıra kullanılacak kesin takvim sayılmaz.</p>'''
nav='<nav><a href="KURASYON-GEREKCESI.html">Neden bu seçki?</a><a href="ILK-14-GUN.html">İlk 14 gün</a><a href="PLAN-180.html">180 gün bölüm taslağı</a><a href="curatorial-decisions.json">Karar kayıtları</a></nav>'
selection='<section class="panel"><h2>İlk altı seçim ve sıralamanın işi</h2><table><tr><th>Gün</th><th>İş / format</th><th>Önermeye katkısı</th><th>Kaynak</th></tr>'
for p in posts:selection+=f'<tr><td>{p["day"]}</td><td>{E(works[p["work_key"]]["title"])} · {E(p["format"])}</td><td>{E(p["curatorial_role"])}</td><td><a href="{MARKET}">{p["work_source_id"]}</a></td></tr>'
selection+='</table><p>Bu bir “görmeden sonraki bölümü anlayamazsın” zinciri değil. Her yayın tek başına anlaşılır; sıralama profili birlikte inceleyen kişiye kişisel kaynak, kamusal imge, beden dili ve tarihli devam arasında bir ilişki sunar. Bu sıranın hesapta daha iyi sonuç verdiği ölçülmedi.</p></section>'
rulehtml='<section class="panel"><h2>Araştırma hangi kararı değiştirdi?</h2>'
for r in rules:rulehtml+=f'<h3>{E(r["id"])} · {E(r["name"])}</h3><p>{E(r["action"])}</p><p><b>Eleme:</b> {E(r["reject"])}</p><p class="muted"><a href="{E(r["source"])}">Araştırma dayanağı</a> · {E(r["status"])}</p>'
rulehtml+='</section>'
hold='<section class="panel"><h2>Neden başka güçlü işler açılışta yok?</h2>'
for r in declined:hold+=f'<h3>{E(works[r["work"]]["title"])}</h3><p>{E(r["decision"])} {E(r["reason"])}</p>'
hold+='</section>'
def card(p):
 b=f'<article class="post" id="day-{p["day"]}"><p class="eyebrow">Gün {p["day"]} · 19.00 Paris · {E(p["format"])}</p><h2>{E(p["title_en"])}</h2><p><b>Neden bu eser:</b> {E(p["why_this_post_tr"])}</p><p><b>Görünür/anlatılmış dayanak:</b> {E(p["proof"])}</p><p><b>Aktarılan taktik:</b> {E(", ".join(p["tactics"]))}</p>'+gallery(p)
 if p.get('social_use_hypothesis'):b+='<p><b>Olası gönderme nedeni:</b> '+E(p['social_use_hypothesis'])+' Bu izleyici davranışı henüz ölçülmedi.</p>'
 if p.get('shots'):
  b+='<h3>Saniyeli üretim kartı</h3><table><tr><th>Çıktı</th><th>Kaynak</th><th>English screen text</th><th>Uygulama</th></tr>'
  for s in p['shots']:
   st=f'{s["source_in"]}–{s["source_out"]} sn' if s['source_in'] is not None else 'Sabit eser kapanışı'
   b+=f'<tr><td>{s["out_start"]}–{s["out_end"]} sn</td><td>{src(s["asset_id"])}<br>{st}</td><td class="english">{E(s["on_screen_en"])}</td><td>{E(s["edit_tr"])}</td></tr>'
  b+='</table>'
 if p.get('voiceover_en'):b+='<h3>English narration · yeni kayıt taslağı</h3><pre>'+E(p['voiceover_en'])+'</pre>'
 b+='<p><b>Ses:</b> '+E(p['sound_tr'])+'</p><details open><summary>English caption</summary><pre>'+E(p['caption_en'])+'</pre><a href="'+p['caption_file']+'">Caption dosyası</a></details>'
 b+='<p><b>Yayın öncesi eleme:</b> '+E(p['rejection_test'])+'</p><p class="muted">Medya renderlenmedi. İngilizce ses metinleri henüz kaydedilmedi. Kaynak zamanları önceki teknik/görsel tarama ve otomatik döküme bağlı; birebir işitsel altyazı kontrolü yapılmış sayılmaz.</p></article>';return b
measure='''<section class="panel"><h2>İlk 14 günün gözlemi neyi değiştirecek?</h2><p>Karakter/kaynak tanınması ile resim pratiğine ilgi ayrı kaydedilir. “Charizard!” tepkisi ile belirli resim/karar/portföy sorusu aynı sonuç değil. Gönderiye atfedilen takip görünüyorsa ayrı; görünmüyorsa tahmin edilmez. 24/72/168 saat yaşında erişim, izleme mevcutsa, paylaşım, kayıt ve esere özgü sorular alınır.</p><p>Sadece bir içerik yüksek izlenirse konu ailesi kazanmış sayılmaz. Gün 14’te üretim yükü ve ilgili devam birlikte görülür. Sonraki seçki, gerçek karşılık ve bölümün sorusuna göre atanır; boş günler rastgele eserle doldurulmaz. İlk altı farklı içerik bir A/B testi değildir.</p><p>İlk üç akış/hafta operasyon denemesi; 19.00 Europe/Paris başlangıç saati. Reklam başlangıcı atanmadı. Eski iş/eskiz haftada 1–2 uygun adayla yer alır; görsel/biçimsel ilişki yazılmadan kota için seçilmez.</p></section>'''
(OUT/'KURASYON-GEREKCESI.html').write_text(head('Seçkinin ve taktiklerin gerekçesi')+intro+nav+selection+rulehtml+hold+measure+'</main></body></html>',encoding='utf8')
first=head('İlk 14 gün · kaynakla gerekçeli içerik kartları')+intro+nav+selection
first+='<p>Gün 2/4/6/7/9/11/13/14 akış yayını yok. Story yalnız yeni bir bağlam veya gerçek cevap varsa; zorunlu sayı yok.</p>'+''.join(card(p) for p in posts)+measure+'</main></body></html>'
