doc=head('180 gün · küratoryal bölüm taslağı')+intro+nav+selection
for c in chapters:
 doc+=f'<section class="panel"><p class="eyebrow">Gün {c["days"][0]}–{c["days"][1]}</p><h2>{E(c["title"])}</h2><p><b>Soru:</b> {E(c["question"])}</p><p>{E(c["argument"])}</p><p><b>Güncel iş havuzu:</b> {E(" · ".join(works[k]["title"] for k in c["current"]))}</p><p><b>Tarihli arşiv:</b> {E(" · ".join(works[k]["title"] for k in c["archive"]))}</p><p class="muted"><a href="{MARKET}">Eser haritası</a> · Bölüm, sonraki eser atamasını gerekçelendirir; burada gelecekteki performans kazananı veya her günün kesin postu ilan edilmez.</p></section>'
doc+=hold+measure+'</main></body></html>'
