errors=[]
for p in posts:
 assert len(p['caption_en'])<2200
 for a in p['assets']:
  if not Path(a['path']).exists():errors.append(a['path'])
 if p.get('shots'):
  assert p['shots'][0]['out_start']==0 and p['shots'][-1]['out_end']==p['duration_seconds']
  for a,b in zip(p['shots'],p['shots'][1:]):assert a['out_end']==b['out_start']
